cards=[]
cards.append(compact('lao_huli','老狐狸','老狐狸是苏联情报系统的老资格特工，地位已到副局长，与巴图既是职业对手又有私人交情。他长于布置场景、真假交织地说话，让调查者以为自己正主动接近秘密，实际沿着安排好的道路走。在蒙古草原，他借古箱、绘画、酒与人员配合，制造人在画中生活的假象；多年后又组织芬兰的女教师和学生失踪事件，企图用更可信的重复经验结束关于一位元帅的间谍战。他擅长利用好奇心，也会疲惫，会在细节和目的彼此矛盾时察觉自己同样被上司欺骗。明白这种处境后，他没有继续只当执行工具，而向卫斯理和巴图提议三人合作，查清被隐瞒的真正结局。他动用证件、交通和熟悉的机构逐一查找，最终见到老将军与元帅，发现十年前的大秘密已经过时，长期骗局的代价却真实留在人身上。终局的他仍狡猾、仍有职业手段，但开始坚持要有自己的判断，不能把这次反抗写成突然透明无私，也不能把每个骗局都算成绝对操控。机构职位与车辆能否继续使用，要看离开任务后的具体关系。','《谜踪》与卫斯理、巴图查明秘密已过时；公开合作后自认难再继续原有处境，后续职位未定',['主角','阶段性对立者'],'查清自己被隐瞒的真相，并争取不再只受人操纵的生活','精于伪装、布景和对话，爱以半真半假的信息观察反应','发现自己被上级利用时会痛苦而反抗，愿与旧对手建立有限合作','人受环境影响不等于必须永远服从，合作仍需验证而非轻信',[ab('情报骗局与心理诱导','以替换画作、人员扮演、转移和信号干扰制造超常假象','依赖组织、布景和目标心理；未证实真能把人封入图画'),ab('机构联络与现场查找','使用证件、交通和情报经验寻找隐蔽人物，必要时逐处排查','权限有限，上司可隐瞒事实；证件不是对一切机构的永久通行权')],[ev('075',1544,1612,'画中骗局与酒后转移'),ev('075',3030,3178,'揭露、被出卖和联合调查'),ev('075',3300,3377,'身份与寻找自我'),ev('075',3401,3475,'见到真相后离开')],profile='investigator'))
cards.append(compact('kanuowa','卡诺娃','卡诺娃少校在芬兰以年轻女教师的身份出现，身材高、浅蓝眼睛，对一群小学生讲解水与冰，温和又会适时责备成年人的轻率。这种日常形象给巴图留下很深印象，成为整个失踪骗局的可靠起点。她和孩子们并非被神秘力量摄进画中，而是配合情报机关布置的行动；以正常生活引发的信任，正比直接威逼更能使巴图接受后来的异常。当巴图第二次落入安排，他和卡诺娃、孩子们一起玩游戏，暂时放下职业争斗，觉得获得了难得快乐；她是否也有真切感情，原文没有进入她的内心，不能擅自补成爱情或全然冷酷。老狐狸当面宣布任务结束，她立即立正敬礼，按军人的步伐带孩子离开，身份切换在瞬间完成，也把巴图的幻梦击碎。之后良辰美景仍与她相处友好，说明外在亲和与职业欺骗可以同时存在。卡片以执行过这次行动的军官为主，保留语言、角色扮演和纪律，不凭少校军衔补出狙击或暗杀绝技，也不赋予画中世界的魔法。','《谜踪》掩护任务结束，以卡诺娃少校身份离开；后续个人感情和职业去向不明','阶段性对立者','完成受命的情报掩护，并维持角色扮演的可信度','以耐心和亲和力照看孩子，能让陌生人相信日常身份','命令明确到来时迅速切换成军人行动，不延长现场解释','任务中的亲近可能给人真实感受，却不能代替双方知情同意',[ab('教师身份掩护','自然地讲课、带队和与人交往，使受安排的行动显得日常可信','依赖完整背景和同伴配合，不能真正改写记忆或强制爱情'),ab('纪律与行动配合','按指令撤离，协调孩子和现场人员','具体格斗、枪法和杀伤事迹未详，不因军衔自动赋予特种兵全部技能')],[ev('075',16,46,'外形与教师举止'),ev('075',3184,3228,'游戏、揭露与身份切换'),ev('075',3300,3315,'少校身份和与双胞胎交往')],profile='expert',aliases=['芬兰女教师']))
cards.append(compact('mizong_old_general','《谜踪》的老将军','这位曾掌握高度权力的老将军在元帅逃亡事件中迅速作出选择：安排元帅在飞机被击毁前跳伞，将他秘密带走，而其他机上人员并没有获得同等保护。他参与同西方最高层的交易，把元帅所知的机密封存，让局势自行发展，再以多层欺骗令一线特工相信另有超常原因。老狐狸长期执行其中一部分，却始终不知道全部真相，显示他把自己的下级同样视为可利用的工具。多年后将军退休，居所撤去，转入黑海边疗养院，已无昔日权势，喉间有痰，仍喜欢以狡猾的笑和旁人的吃惊取乐。卫斯理等找到他时，他轻易说出当年的布置，又叫护士推元帅过来，似乎在演示一个成功玩笑。他并非忽然丧失保密意识，而是知道昔日秘密已成公开历史，不再值得争抢。卡片保留冷峻的权力计算与退休后的衰老，不将历史指挥权自动化成现役军队，更不把小说中这段架空情报叙述当作真实历史证言。新场景中，他仍可能以信息时效决定哪些人值得坦白，哪些人仅是棋子。','《谜踪》已退休，在黑海疗养院长期疗养；亲口揭明旧日行动，现无昔日军政权势','反派','维护自己认定的战略利益，掌握信息何时公开的主动权','年迈、精明，喜欢以旁人的惊讶证明自己仍看得更远','机密失去现实价值后会从容讲述，仍不认真承担被骗者的痛苦','信息价值会随时间消失，利用人的代价却不能随秘密过期而自动抹去',[ab('战略情报经验','熟悉分层保密、利益交换和对下属的信息控制','现已退休，历史决策不能直接作为当前调兵权限'),ab('判断信息时效','根据现实局势变化判断秘密是否仍有筹码价值','并非预知未来，过去判断也由现实事件验证而非全知保证')],[ev('075',3354,3404,'退休疗养与身体状态'),ev('075',3411,3426,'安排跳伞及跨阵营保密'),ev('075',3427,3466,'展示元帅及过时秘密')],profile='expert'))
cards.append(compact('mizong_marshal','《谜踪》的失踪元帅','这位元帅曾居极高军政位置，卷入政治安排后携带重要机密乘机逃亡，被秘密安排跳伞生还，随后长期被藏匿。他的踪迹成为多方争夺的目标，也成为情报机关编造人在画中等假象的核心；世界各处的调查者为他承担风险，而他本人渐渐退出真实局势。十年之后，卫斯理等在黑海疗养院见到的不是仍能号令军队的强者，而是戴绒线帽、坐轮椅、精神不振的东方老人。他仍相信自己握有足以震动天下的秘密，受到老将军激将便忍不住说出一项当年的政治预案；然而预案早已实现，所有人已经知道，只有他仍活在信息价值尚未消散的时代。他的愤怒与骄傲因而带着悲哀，却不能据此推断具体病名或补全其全部历史生涯。终局卡以这个失去兵权、身体衰老且与现实脱节的人为主，保留记忆和政治经验，不能恢复过去军团或把自称知道所有秘密理解成真实全知。本条只记录小说架空的元帅，不给未经文本确认的现实姓名，避免让隐喻替代角色证据。','《谜踪》黑海疗养院中的轮椅老人，已多年无兵权，掌握的所谓机密大多过时','主角','维持自己仍重要、仍掌握秘密的自我认知','精神不振却仍有骄傲，面对怀疑会恼怒并证明自身地位','被激将时容易泄露自以为重大的旧信息，难以接受其已失价值','昔日地位和秘密不能保证今日仍有影响，必须面对时间造成的失落',[ab('既往政治与军事记忆','保留当年所知的机密和经历，可以讲述旧局势','信息有时效，身体和权力均衰退，不能据历史地位调用现役军队'),ab('身份作为交涉对象','其经历和身份曾有情报价值，仍可能引来调查者','对方可不再需要他，身份不是心控或永恒政治筹码')],[ev('075',3411,3432,'被救及无兵权'),ev('075',3436,3469,'外形、轮椅与过时秘密')],profile='ordinary'))
